data.CSS:
@font-face { font-family:"Plus Jakarta Sans"; font-weight:200 800; font-display:swap; src:url("/fonts/plus-jakarta-sans-variable.woff2") format("woff2"); }
@font-face { font-family:"Inter"; font-weight:400; font-display:swap; src:url("/fonts/inter-400.woff2") format("woff2"); }
@font-face { font-family:"Inter"; font-weight:600; font-display:swap; src:url("/fonts/inter-600.woff2") format("woff2"); }
:root { --pine:#1E4D4A; --pine-deep:#163A38; --sage:#E3EDE7; --mist:#F6F9F7; --amber:#D9A24B; --ink:#1B2A2A; --muted:#475857; --rule:#D3DFD9;
  --display:"Plus Jakarta Sans", system-ui, sans-serif; --body:"Inter", system-ui, sans-serif; }
* { box-sizing:border-box; }
body { margin:0; background:var(--mist); color:var(--ink); font:17px/1.65 var(--body); }
img { display:block; max-width:100%; height:auto; }
a { color:var(--pine); text-decoration-color:var(--amber); text-underline-offset:.2em; }
a:hover { text-decoration-thickness:2px; }
h1, h2, h3 { font-family:var(--display); font-weight:700; color:var(--pine); line-height:1.2; letter-spacing:-.01em; margin:0 0 .5em; }
h1 { font-size:clamp(2rem, 3.6vw, 2.9rem); }
h2 { font-size:clamp(1.4rem, 2.4vw, 1.85rem); }
h3 { font-size:1.2rem; }
.o-wrap { max-width:70rem; margin:0 auto; padding:0 1.25rem; }
.o-narrow { max-width:44rem; }
.o-skip { position:absolute; left:1rem; top:-3rem; z-index:10; background:var(--pine); color:#fff; padding:.5rem 1rem; border-radius:.4rem; font-weight:600; }
.o-skip:focus { top:1rem; }
.o-header { background:#fff; border-bottom:1px solid var(--rule); }
.o-header .o-wrap { display:flex; flex-wrap:wrap; align-items:center; gap:.75rem 2rem; padding-top:1rem; padding-bottom:1rem; }
.o-brand { display:flex; align-items:center; gap:.6rem; font-family:var(--display); font-weight:700; font-size:1.4rem; color:var(--pine); text-decoration:none; }
.o-brand::before { content:""; width:.9rem; height:.9rem; border-radius:50% 50% 50% 0; background:var(--amber); transform:rotate(-45deg); }
.o-nav ul, .o-langs { display:flex; flex-wrap:wrap; gap:.25rem 1.4rem; list-style:none; margin:0; padding:0; }
.o-nav a { color:var(--ink); text-decoration:none; font-weight:600; }
.o-nav a:hover, .o-nav a[aria-current=page] { color:var(--pine); text-decoration:underline; text-decoration-color:var(--amber); text-decoration-thickness:2px; text-underline-offset:.45em; }
.o-nav a.is-ancestor { color:var(--pine); }
.o-langs { margin-left:auto; font-size:.85rem; }
.o-langs a { color:var(--pine); text-decoration:none; text-transform:uppercase; letter-spacing:.06em; font-weight:600; border:1px solid var(--rule); border-radius:999px; padding:.15rem .65rem; }
.o-langs a:hover { border-color:var(--pine); }
.o-hero { background:var(--sage); }
.o-hero .o-wrap { display:grid; grid-template-columns:minmax(0, 5fr) minmax(0, 6fr); gap:2.5rem; align-items:center; padding-top:3.5rem; padding-bottom:3.5rem; }
.o-hero img { width:100%; aspect-ratio:16/10; object-fit:cover; border-radius:1.25rem; }
.o-hero p { font-size:1.15rem; color:var(--muted); margin:0 0 1.5rem; max-width:34rem; }
.o-button { display:inline-block; background:var(--pine); color:#fff; font-weight:600; text-decoration:none; padding:.8rem 1.6rem; border-radius:999px; }
.o-button:hover { background:var(--pine-deep); }
button.o-button { border:0; cursor:pointer; font:inherit; font-weight:600; }
.o-more { font-weight:600; }
.o-section { padding:3.5rem 0; }
.o-band { background:#fff; border-top:1px solid var(--rule); border-bottom:1px solid var(--rule); }
.o-lead { font-size:1.15rem; color:var(--muted); max-width:44rem; }
.o-cards { display:grid; gap:1.5rem; grid-template-columns:repeat(auto-fill, minmax(15rem, 1fr)); list-style:none; margin:2rem 0; padding:0; }
.o-card { background:#fff; border:1px solid var(--rule); border-radius:.9rem; overflow:hidden; display:flex; flex-direction:column; }
.o-band .o-card { background:var(--mist); }
.o-card img { width:100%; aspect-ratio:3/2; object-fit:cover; object-position:center 25%; }
.o-card-body { padding:1.1rem 1.25rem 1.4rem; }
.o-card h2, .o-card h3 { font-size:1.2rem; margin-bottom:.25rem; }
.o-card p { margin:0; color:var(--muted); }
.o-card .o-role { color:var(--pine); font-weight:600; font-size:.95rem; margin-bottom:.4rem; }
.o-split { display:grid; gap:2.5rem; grid-template-columns:minmax(0, 1fr) minmax(0, 1fr); align-items:center; }
.o-split img { border-radius:1rem; width:100%; aspect-ratio:3/2; object-fit:cover; }
.o-figure { margin:0 0 2rem; }
.o-figure img { border-radius:1rem; width:100%; }
.o-prose p, .o-prose ul { margin:0 0 1.1rem; }
.o-prose li { margin-bottom:.35rem; }
.o-page section { margin-bottom:2.5rem; }
.o-page section + section { padding-top:2rem; border-top:1px solid var(--rule); }
.o-form { display:grid; gap:1rem; max-width:34rem; margin-top:1.5rem; padding:1.5rem; background:#fff; border:1px solid var(--rule); border-radius:.9rem; }
.o-field { margin:0; }
.o-field label { display:block; font-weight:600; margin-bottom:.3rem; }
.o-field input, .o-field textarea { width:100%; padding:.65rem .8rem; font:inherit; color:var(--ink); background:var(--mist); border:1px solid var(--rule); border-radius:.5rem; }
.o-field input:focus, .o-field textarea:focus { outline:2px solid var(--pine); outline-offset:1px; }
.o-field textarea { min-height:6rem; }
.o-footer { background:var(--pine-deep); color:var(--sage); padding:2.5rem 0; margin-top:3rem; font-size:.95rem; }
.o-footer a { color:#fff; }
.o-footer .o-wrap { display:flex; flex-wrap:wrap; justify-content:space-between; gap:1rem; }
.o-footer strong { font-family:var(--display); color:#fff; }
@media (max-width: 48rem) { .o-hero .o-wrap, .o-split { grid-template-columns:1fr; } .o-hero .o-wrap { padding-top:2rem; padding-bottom:2.5rem; } .o-langs { margin-left:0; } }
